content.text:
{
  "name": "VICP网络仪器会话组件",
  "name_en": "VICP Network Instrument Session Component",
  "manufacturer": "",
  "description": "这是一个非物理的软件通信组件，用于通过 TCP/IP 上的 VICP 协议与实验仪器建立会话并进行资源访问。它提供资源枚举、读写、清除、触发、锁定及连接参数管理等能力，适合在自动化实验中作为远程仪器通信层使用。",
  "description_en": "This is a non-physical software communication component for creating sessions to laboratory instruments over TCP/IP using the VICP protocol. It provides resource listing, read/write I/O, clear, trigger, lock, and connection-parameter management, and is used as a remote instrument communication layer in lab automation.",
  "actions": [
    {
      "action_name": "auto-after_parsing",
      "description": "初始化并配置会话属性。",
      "description_en": "Initialize and configure session attributes."
    },
    {
      "action_name": "auto-set_keepalive",
      "description": "设置 TCP keepalive 连接属性。",
      "description_en": "Set the TCP keepalive connection property."
    },
    {
      "action_name": "auto-close",
      "description": "关闭 VICP 网络会话。",
      "description_en": "Close the VICP network session."
    },
    {
      "action_name": "auto-read",
      "description": "从远程仪器同步读取数据。",
      "description_en": "Read data synchronously from the remote instrument."
    },
    {
      "action_name": "auto-write",
      "description": "向远程仪器同步写入数据。",
      "description_en": "Write data synchronously to the remote instrument."
    },
    {
      "action_name": "auto-clear",
      "description": "清除远程设备状态或缓冲。",
      "description_en": "Clear the remote device state or buffers."
    },
    {
      "action_name": "auto-list_resources",
      "description": "列出可用的网络仪器资源。",
      "description_en": "List available network instrument resources."
    },
    {
      "action_name": "auto-get_low_level_info",
      "description": "获取底层通信信息。",
      "description_en": "Get low-level communication information."
    },
    {
      "action_name": "auto-get_max_message_kb",
      "description": "get 最大消息大小（KB）",
      "description_en": "get the maximum message size (KB)"
    },
    {
      "action_name": "auto-set_max_message_kb",
      "description": "set 最大消息大小（KB）",
      "description_en": "set the maximum message size (KB)"
    },
    {
      "action_name": "auto-get_keepalive",
      "description": "get TCP keepalive 连接属性",
      "description_en": "get the TCP keepalive connection property"
    },
    {
      "action_name": "auto-read_stb",
      "description": "读取仪器状态字节。",
      "description_en": "Read the instrument status byte."
    },
    {
      "action_name": "auto-assert_trigger",
      "description": "向远程仪器发送触发命令。",
      "description_en": "Assert a trigger to the remote instrument."
    },
    {
      "action_name": "auto-lock",
      "description": "锁定会话或资源访问。",
      "description_en": "Lock the session or resource access."
    },
    {
      "action_name": "auto-unlock",
      "description": "解锁会话或资源访问。",
      "description_en": "Unlock the session or resource access."
    },
    {
      "action_name": "auto-flush",
      "description": "刷新通信缓冲区。",
      "description_en": "Flush the communication buffers."
    },
    {
      "action_name": "auto-remove_service",
      "description": "移除已注册的服务处理项。",
      "description_en": "Remove a registered service handler."
    },
    {
      "action_name": "auto-add_service",
      "description": "添加服务处理项。",
      "description_en": "Add a service handler."
    }
  ],
  "tag_hints": [
    "VICP protocol",
    "TCP/IP instrument session",
    "VISA resource communication",
    "network instrument I/O",
    "remote instrument control",
    "session keepalive",
    "instrument resource listing"
  ]
}

